                    r4=_mm512_load_pd(s0+4*ES+8); r5=_mm512_load_pd(s0+5*ES+8); r6=_mm512_load_pd(s0+6*ES+8); r7=_mm512_load_pd(s0+7*ES+8);
                    TR8(r0,r1,r2,r3,r4,r5,r6,r7,o0,o1,o2,o3,o4,o5,o6,o7);
